<script setup lang="ts">
import {computed,ref,onUnmounted} from 'vue';
import type {Category} from '@/domain/types';
const props=defineProps<{modelValue?:string;categories:Category[];rootOnly?:boolean;unboundLabel?:string;compact?:boolean;loadCategories?:()=>Promise<Category[]>}>();
const emit=defineEmits<{'update:modelValue':[id:string]}>();
const opened=ref(false),query=ref(''),loading=ref(false),error=ref(''),loaded=ref<Category[]|null>(null);let request=0;
const available=computed(()=>loaded.value??props.categories);
onUnmounted(()=>{request++;});
const current=computed(()=>available.value.find(c=>c.id===props.modelValue));
const results=computed(()=>available.value.filter(c=>(!props.rootOnly||c.parentId===undefined||c.parentId===''||c.parentId==='0')&&(c.name+' '+c.id).toLowerCase().includes(query.value.trim().toLowerCase())));
function choose(id:string){emit('update:modelValue',id);opened.value=false;query.value='';}
async function refresh(){if(!props.loadCategories)return;const generation=++request;loading.value=true;error.value='';loaded.value=[];try{const items=await props.loadCategories();if(generation===request)loaded.value=items;}catch(e){if(generation===request)error.value=(e as Error).message||'读取分类失败';}finally{if(generation===request)loading.value=false;}}
function open(){query.value='';opened.value=true;void refresh();}
</script>
<template><view class="category-binding">
<button class="binding-trigger" :class="{compact}" :aria-label="modelValue?'更改绑定分类':'绑定分类'" @click="open"><view v-if="!compact"><text class="binding-label">{{current?.name||(modelValue?'已绑定分类 #'+modelValue:(unboundLabel||'未绑定'))}}</text><text class="binding-id" v-if="modelValue">分类 ID：{{modelValue}}</text></view><text class="binding-action">{{compact?'绑定':modelValue?'更改绑定':'绑定分类'}}{{compact?'':' ›'}}</text></button>
<view v-if="opened" class="binding-mask" @click.self="opened=false"><view class="binding-dialog" role="dialog" aria-modal="true" aria-label="绑定 CMS 分类"><view class="binding-head"><text>绑定 CMS 分类</text><button aria-label="关闭分类选择" @click="opened=false">关闭</button></view><text class="binding-hint">{{rootOnly?'仅列出内容源的一级分类，点击后绑定真实 ID。':'点击分类进行绑定。'}}</text><input class="binding-search" v-model="query" placeholder="搜索分类名称或 ID" aria-label="搜索 CMS 分类"/><text v-if="loading" class="binding-empty" role="status">正在读取 CMS 一级分类…</text><view v-else-if="error" class="binding-empty" role="alert">{{error}}<button @click="refresh">重新读取</button></view><scroll-view v-else scroll-y class="binding-options"><button class="binding-option" @click="choose('')"><text>{{unboundLabel||'解除绑定'}}</text><text v-if="!modelValue">✓</text></button><button v-for="c in results" :key="c.id" class="binding-option" :class="{selected:modelValue===c.id}" @click="choose(c.id)"><view><text>{{c.name}}</text><text class="binding-id">ID：{{c.id}}</text></view><text>{{modelValue===c.id?'✓':'绑定'}}</text></button><view class="binding-empty" v-if="!available.length">暂无可绑定分类，请先在内容连接中连接苹果 CMS。</view><view class="binding-empty" v-else-if="!results.length">没有找到匹配的分类</view></scroll-view></view></view>
</view></template>
<style scoped>
.binding-trigger{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;margin:0;padding:12px;background:var(--studio-input,#172329);border:1px solid var(--studio-border,#ffffff12);border-radius:8px;line-height:1.5;font-size:12px;color:var(--studio-text,#d8e3df)}
.binding-trigger::after,.binding-dialog button::after{border:0}.binding-label{display:block}.binding-id{display:block;font-size:10px;color:var(--studio-muted,#819895);margin-top:3px}.binding-action{font-size:11px;color:var(--studio-link,#c9eaa2);flex-shrink:0}
.binding-mask{position:fixed;inset:0;z-index:1000;display:flex;align-items:center;justify-content:center;background:#0009;padding:24px;box-sizing:border-box}.binding-dialog{width:440px;max-width:100%;padding:22px;background:var(--studio-panel,#111b21);color:var(--studio-text,#d8e3df);border:1px solid var(--studio-border,#ffffff12);border-radius:16px;box-shadow:0 24px 80px #0005;box-sizing:border-box}.binding-head{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:16px;font-weight:600}.binding-head button{margin:0;padding:4px 10px;font-size:12px;line-height:2;background:var(--studio-input,#172329);color:var(--studio-muted,#819895)}.binding-hint{display:block;margin:12px 0;font-size:12px;color:var(--studio-muted,#819895);line-height:1.7}.binding-search{box-sizing:border-box;min-height:44px;padding:10px 12px;border:1px solid var(--studio-border,#ffffff12);border-radius:8px;background:var(--studio-input,#172329);font-size:13px}.binding-options{max-height:360px;margin-top:12px}.binding-option{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;margin:0 0 6px;padding:12px;text-align:left;font-size:13px;line-height:1.6;border-radius:8px;color:var(--studio-text,#d8e3df);background:var(--studio-input,#172329)}.binding-option>text:last-child{color:var(--studio-link,#c9eaa2);font-size:11px}.binding-option.selected{box-shadow:inset 0 0 0 1px var(--studio-link,#c9eaa2)}.binding-empty{padding:22px 12px;font-size:12px;line-height:1.8;text-align:center;color:var(--studio-muted,#819895)}
.binding-trigger.compact{width:auto;padding:4px 12px;min-height:38px;border-radius:6px;white-space:nowrap}.binding-empty button{margin:10px auto 0;font-size:12px;color:var(--studio-link,#c9eaa2);background:var(--studio-input,#172329)}
</style>
